  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Tasimelteon, the closest structural analogue (Morgan 0.49), has an absolute oral bioavailability of 38% in humans, above the 20% threshold; however, its cyclopropyl-benzofuran scaffold is less fused and metabolically labile than the query's tricyclic indeno-furan, limiting transferability of this high-F result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Darifenacin, which contains a dihydrobenzofuran moiety related to the query's fused ether system, has an oral bioavailability of only 15–19% in humans due to low solubility and high first-pass metabolism, supporting a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "MK-458, a tricyclic fused-ether compound, shows an absolute oral bioavailability of approximately 5% in humans after intravenous comparison, demonstrating that this scaffold class can undergo extensive first-pass metabolism and yield F well below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low (<20%) absolute oral bioavailability. The query's fused tricyclic indeno-furan ether is more metabolically labile than the closest analogue tasimelteon (F=38%), and low-F analogues with related fused ether/benzofuran scaffolds (darifenacin 15–19%, MK-458 ~5%) support extensive first-pass metabolism.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "The closest high-F analogue (tasimelteon) differs in ring fusion, and the low-F analogues contain additional liabilities (phenol, basic amine) not present in the query.",
    "Fasted-state-specific data are not consistently reported across evidence records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

